const crypto = require("crypto");
const envelope = $json;
const body = envelope.body ?? envelope;
const headers = envelope.headers ?? {};
const signature = String(headers["x-ff-signature"] ?? "");
const timestamp = String(headers["x-ff-timestamp"] ?? "");
const nonce = String(headers["x-ff-nonce"] ?? "");
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) throw new Error("Missing N8N_WEBHOOK_SECRET in n8n environment");
if (!signature || !timestamp || !nonce) throw new Error("Missing CP request signature headers");
if (!body.job_id || !body.correlation_id || !body.callback_url) throw new Error("Missing job_id, correlation_id, or callback_url");
if (body.workflow_type !== "creative_image_generation") throw new Error("Unexpected workflow_type");
const drift = Math.abs(Date.now() - Date.parse(timestamp));
if (!Number.isFinite(drift) || drift > 5 * 60 * 1000) throw new Error("CP request timestamp rejected");
const raw = JSON.stringify(body);
const expected = crypto.createHmac("sha256", secret).update(timestamp + "." + nonce + "." + raw).digest("hex");
const supplied = Buffer.from(signature, "hex");
const calculated = Buffer.from(expected, "hex");
if (supplied.length !== calculated.length || !crypto.timingSafeEqual(supplied, calculated)) throw new Error("Invalid CP request signature");
return [{ json: { cp: body, accepted: true, received_at: new Date().toISOString() } }];

const fs = require("fs");
const path = require("path");

const cp = $json.cp;
const payload = cp.payload ?? {};

const baseDir = path.resolve(String($env.BRAND_ASSETS_BASE_DIR || "/data/brand-assets"));

const idPattern = /^[a-z0-9][a-z0-9-]{0,63}$/;

const brandId = String(payload.brand_id || "future-oils");
const logoId = String(payload.logo_id || "primary");
const ratio = String(payload.ratio || "4:5");

if (!idPattern.test(brandId) || !idPattern.test(logoId)) {
  throw new Error("Invalid brand asset identifier");
}

if (!new Set(["4:5", "1:1", "9:16"]).has(ratio)) {
  throw new Error("Unsupported creative ratio");
}

const profilePath = path.resolve(baseDir, "brand-profile.json");

if (!profilePath.startsWith(baseDir + path.sep)) {
  throw new Error("Brand profile path escaped asset root");
}

const profile = JSON.parse(fs.readFileSync(profilePath, "utf8"));

if (profile.brand_id !== brandId) {
  throw new Error("Requested brand profile is unavailable");
}

function resolveAsset(relative) {
  if (!relative || typeof relative !== "string") {
    throw new Error("Brand asset is missing from profile");
  }

  const absolute = path.resolve(baseDir, relative);

  if (!absolute.startsWith(baseDir + path.sep)) {
    throw new Error("Brand asset path escaped asset root");
  }

  if (!fs.statSync(absolute).isFile()) {
    throw new Error("Brand asset file is unavailable: " + absolute);
  }

  return absolute;
}

function normalizeArabicDigits(value) {
  const arabicIndic = "٠١٢٣٤٥٦٧٨٩";
  const easternArabicIndic = "۰۱۲۳۴۵۶۷۸۹";

  return String(value || "").replace(/[٠-٩۰-۹]/g, (digit) => {
    const a = arabicIndic.indexOf(digit);
    if (a >= 0) return String(a);

    const e = easternArabicIndic.indexOf(digit);
    if (e >= 0) return String(e);

    return digit;
  });
}

function normalizeText(value) {
  return normalizeArabicDigits(value)
    .toLowerCase()
    .replace(/&/g, " and ")
    .replace(/[._/\\]+/g, " ")
    .replace(/[-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function compactText(value) {
  return normalizeText(value).replace(/\s+/g, "");
}

function getPayloadSearchText(payload) {
  return [
    payload.product_asset_id,
    payload.product_key,
    payload.product_code,
    payload.product_id,
    payload.sku,
    payload.product_sku,
    payload.product,
    payload.product_name,
    payload.title,
    payload.headline,
    payload.description,
    payload.size,
    payload.capacity,
    payload.volume,
    payload.package_size,
    payload.pack_size
  ]
    .filter((value) => value !== null && value !== undefined && String(value).trim())
    .map(String)
    .join(" ");
}

/**
 * Extract liter capacity from payload.
 * Supports:
 * 5L
 * 5 L
 * 5-liter
 * 5 liter
 * 5 litres
 * 5 ltr
 * 5 لتر
 * ٥ لتر
 */
function extractCapacityLiters(payload) {
  const explicitFields = [
    payload.capacity_liters,
    payload.capacity_litre,
    payload.volume_liters,
    payload.volume_litre,
    payload.liters,
    payload.litres,
    payload.size_liters,
    payload.size_litre,
    payload.pack_size_liters,
    payload.pack_size_litre
  ];

  for (const value of explicitFields) {
    const number = Number(normalizeArabicDigits(value));

    if (Number.isFinite(number) && number > 0 && number <= 100) {
      return number;
    }
  }

  const text = normalizeText(getPayloadSearchText(payload));

  const patterns = [
    /(?:^|\D)(\d+(?:\.\d+)?)\s*(?:l|lt|ltr|liter|liters|litre|litres|لتر|ليتر)(?:\D|$)/i,
    /(?:^|\D)(\d+(?:\.\d+)?)\s*[- ]?\s*(?:l|lt|ltr)(?:\D|$)/i
  ];

  for (const pattern of patterns) {
    const match = text.match(pattern);

    if (match) {
      const number = Number(match[1]);

      if (Number.isFinite(number) && number > 0 && number <= 100) {
        return number;
      }
    }
  }

  /**
   * Fallback:
   * لو لم نجد وحدة L/لتر، نبحث عن رقم واضح من السعات المعروفة.
   * رتبنا 18 و13 و12 و10 قبل 1 و2 حتى لا يلتقط رقم 1 من 10 أو 12.
   */
  const knownSizes = [18, 13, 12, 10, 5, 4, 3, 2, 1];

  for (const size of knownSizes) {
    const re = new RegExp("(^|\\D)" + size + "(\\D|$)", "i");

    if (re.test(text)) {
      return size;
    }
  }

  return null;
}

function productCandidateText(productId, product) {
  return [
    productId,
    product?.id,
    product?.key,
    product?.sku,
    product?.code,
    product?.name,
    product?.title,
    product?.label,
    product?.description,
    product?.size,
    product?.capacity,
    product?.volume,
    product?.package_size,
    product?.pack_size,
    product?.file
  ]
    .filter((value) => value !== null && value !== undefined && String(value).trim())
    .map(String)
    .join(" ");
}

function productHasCapacity(productId, product, capacityLiters) {
  if (!capacityLiters) return false;

  const numericFields = [
    product?.capacity_liters,
    product?.capacity_litre,
    product?.volume_liters,
    product?.volume_litre,
    product?.liters,
    product?.litres,
    product?.size_liters,
    product?.size_litre,
    product?.pack_size_liters,
    product?.pack_size_litre
  ];

  for (const value of numericFields) {
    const number = Number(normalizeArabicDigits(value));

    if (Number.isFinite(number) && number === capacityLiters) {
      return true;
    }
  }

  const text = normalizeText(productCandidateText(productId, product));
  const compact = compactText(productCandidateText(productId, product));

  const size = String(capacityLiters).replace(/\.0+$/, "");

  const capacityPatterns = [
    new RegExp("(^|\\D)" + size + "\\s*(l|lt|ltr|liter|liters|litre|litres|لتر|ليتر)(\\D|$)", "i"),
    new RegExp("(^|\\D)" + size + "\\s*[- ]?\\s*(l|lt|ltr)(\\D|$)", "i"),
    new RegExp("(^|\\D)" + size + "\\s*لتر(\\D|$)", "i")
  ];

  if (capacityPatterns.some((pattern) => pattern.test(text))) {
    return true;
  }

  const compactPatterns = [
    size + "l",
    size + "lt",
    size + "ltr",
    size + "liter",
    size + "litre",
    size + "liters",
    size + "litres",
    size + "لتر",
    size + "ليتر"
  ];

  if (compactPatterns.some((token) => compact.includes(token))) {
    return true;
  }

  /**
   * Fallback مضبوط:
   * يطابق الرقم كجزء مستقل في product id أو اسم الملف أو الاسم.
   */
  const standaloneNumber = new RegExp("(^|\\D)" + size + "(\\D|$)", "i");

  return standaloneNumber.test(text);
}

function scoreProductMatch(productId, product, payload, capacityLiters) {
  const searchText = normalizeText(getPayloadSearchText(payload));
  const searchCompact = compactText(getPayloadSearchText(payload));

  const candidateText = normalizeText(productCandidateText(productId, product));
  const candidateCompact = compactText(productCandidateText(productId, product));

  let score = 0;
  const reasons = [];

  const explicitKeys = [
    payload.product_asset_id,
    payload.product_key,
    payload.product_code,
    payload.product_id,
    payload.sku,
    payload.product_sku
  ]
    .filter((value) => value !== null && value !== undefined && String(value).trim())
    .map((value) => compactText(value));

  const productIdCompact = compactText(productId);

  for (const key of explicitKeys) {
    if (!key) continue;

    if (productIdCompact === key) {
      score += 1000;
      reasons.push("exact explicit key match");
    } else if (candidateCompact.includes(key) || key.includes(productIdCompact)) {
      score += 600;
      reasons.push("partial explicit key match");
    }
  }

  if (capacityLiters && productHasCapacity(productId, product, capacityLiters)) {
    score += 300;
    reasons.push("capacity match " + capacityLiters + "L");
  }

  /**
   * Product/category hints.
   */
  const categoryWords = [
    "sunflower",
    "refined",
    "oil",
    "زيت",
    "دوار",
    "الشمس"
  ];

  for (const word of categoryWords) {
    if (searchCompact.includes(compactText(word)) && candidateCompact.includes(compactText(word))) {
      score += 20;
      reasons.push("category word match: " + word);
    }
  }

  /**
   * Prefer marketing-approved products.
   */
  if (product?.approved_for_marketing === true) {
    score += 25;
    reasons.push("approved for marketing");
  }

  return {
    productId,
    product,
    score,
    reasons
  };
}

function findProductAssetId(profile, payload) {
  const products = profile.products || {};
  const productIds = Object.keys(products);

  if (!productIds.length) {
    return {
      product_asset_id: null,
      reason: "brand profile has no products",
      capacity_liters: null,
      candidates: []
    };
  }

  /**
   * 1. Exact product_asset_id if provided.
   */
  const explicitProductAssetId = String(payload.product_asset_id || "").trim();

  if (explicitProductAssetId) {
    const normalizedExplicit = compactText(explicitProductAssetId);

    const exactId = productIds.find((id) => compactText(id) === normalizedExplicit);

    if (exactId) {
      return {
        product_asset_id: exactId,
        reason: "matched explicit product_asset_id",
        capacity_liters: extractCapacityLiters(payload),
        candidates: [{ productId: exactId, score: 1000, reasons: ["explicit product_asset_id"] }]
      };
    }
  }

  const capacityLiters = extractCapacityLiters(payload);

  const scored = productIds
    .map((productId) => scoreProductMatch(productId, products[productId], payload, capacityLiters))
    .filter((candidate) => candidate.score > 0)
    .sort((a, b) => b.score - a.score);

  if (!scored.length) {
    return {
      product_asset_id: null,
      reason: "no product matched payload text or capacity",
      capacity_liters: capacityLiters,
      candidates: []
    };
  }

  const best = scored[0];

  return {
    product_asset_id: best.productId,
    reason: "selected highest scoring product match",
    capacity_liters: capacityLiters,
    candidates: scored.slice(0, 5).map((candidate) => ({
      productId: candidate.productId,
      score: candidate.score,
      reasons: candidate.reasons
    }))
  };
}

const logoRelative = profile.logos?.[logoId];

if (!logoRelative) {
  throw new Error("Requested logo asset is unavailable");
}

const productResolution = findProductAssetId(profile, payload);
const productAssetId = productResolution.product_asset_id;
const product = productAssetId ? profile.products?.[productAssetId] : null;

if (productAssetId && !product) {
  throw new Error("Requested product asset is unavailable: " + productAssetId);
}

if (product && product.approved_for_marketing !== true) {
  throw new Error(product.restriction || "Requested product asset is not approved for marketing");
}

return [
  {
    json: {
      cp,
      asset_contract: {
        brand_id: brandId,
        logo_id: logoId,
        product_asset_id: productAssetId,
        product_resolution: productResolution,
        ratio,
        profile_version: profile.schema_version,
        brand_theme: profile.brand_theme || {},
        layout_rules: profile.layout_rules || {},
        logo_path: resolveAsset(logoRelative),
        product_path: product ? resolveAsset(product.file) : null
      }
    }
  }
];

const item = $json;

/**
 * Light premium background only.
 * Magnific مسؤول عن الخلفية فقط، وليس عن الإعلان.
 */
const prompt = [
  "Create an empty bright luxury abstract studio backdrop only.",
  "This is not an advertisement, not a poster, and not a product mockup.",
  "The image must be a clean blank background plate only.",
  "Use a high-key bright composition with warm ivory, cream, soft beige, pale gold, and very subtle light olive accents.",
  "The overall background must be light, airy, clean, premium, and elegant.",
  "Avoid dark areas, dark green blocks, heavy shadows, black tones, brown tones, and deep olive backgrounds.",
  "Use only smooth abstract curves, elegant soft gradients, gentle highlights, clean depth, and premium studio lighting.",
  "Keep the central vertical area bright and clean for a large product packshot to be added later.",
  "Keep the lower area bright and calm for text to be added later.",
  "Absolutely no text of any kind.",
  "No typography. No letters. No numbers. No words. No readable text. No fake text. No gibberish text. No handwriting. No printed marks.",
  "No objects. No products. No bottles. No packages. No labels. No sunflowers. No seeds. No oil splashes.",
  "No logos. No icons. No badges. No certificates. No QR codes. No signs. No posters. No UI elements.",
  "No people. No faces. No portraits. No models. No hands. No body parts. No businessperson. No character.",
  "Final result: an empty bright premium beige and pale gold abstract studio background only."
].join(" ");

return [
  {
    json: {
      ...item,
      mcp_generate_args: {
        prompt
      },
      requested_output: {
        type: "background",
        aspect_ratio: item.asset_contract.ratio,
        review_required: true
      }
    }
  }
];

function parseMaybeJson(value) {
  if (typeof value !== "string") return value;
  try { return JSON.parse(value); } catch { return value; }
}
function collectCandidates(value, output = []) {
  const parsed = parseMaybeJson(value);
  if (parsed && typeof parsed === "object") {
    output.push(parsed);
    if (Array.isArray(parsed.content)) {
      for (const item of parsed.content) {
        if (item?.type === "text") collectCandidates(item.text, output);
        else collectCandidates(item, output);
      }
    }
    if (parsed.structuredContent) collectCandidates(parsed.structuredContent, output);
  }
  return output;
}
function findByKeys(value, keys, seen = new Set()) {
  if (!value || typeof value !== "object" || seen.has(value)) return undefined;
  seen.add(value);
  if (Array.isArray(value)) {
    for (const item of value) {
      const found = findByKeys(item, keys, seen);
      if (found) return found;
    }
    return undefined;
  }
  for (const key of keys) {
    const candidate = value[key];
    if (typeof candidate === "string" && candidate.trim()) return candidate.trim();
    if (typeof candidate === "number" && Number.isFinite(candidate)) return String(candidate);
  }
  for (const nested of Object.values(value)) {
    const found = findByKeys(nested, keys, seen);
    if (found) return found;
  }
  return undefined;
}
const built = $("Build Background Prompt").item.json;
const generationResult = $json;
const candidates = collectCandidates(generationResult);
let creationId;
for (const candidate of candidates) {
  creationId = findByKeys(candidate, ["identifier", "id", "creation_id", "creationId", "task_id", "taskId", "job_id", "jobId"]);
  if (creationId) break;
}
if (!creationId) {
  throw new Error("Magnific MCP images_generate did not return a creation identifier. Open this execution, inspect the MCP output, and adjust Prepare Magnific Wait Input to the live tools/list schema.");
}
return [{ json: {
  cp: built.cp,
  mcp_endpoint: built.mcp_endpoint,
  generation_result: generationResult,
  creation_id: creationId,
  mcp_wait_args: { identifiers: [creationId] }
} }];

const sharp = require("sharp");
const fs = require("fs");
const http = require("http");
const https = require("https");

/**
 * Parse JSON if a value is JSON text.
 */
function parseMaybeJson(value) {
  if (typeof value !== "string") return value;

  try {
    return JSON.parse(value);
  } catch {
    return value;
  }
}

/**
 * Force any //domain/path URL to become https://domain/path
 */
function normalizeImageUrl(value) {
  if (value === null || value === undefined) return "";

  let url = String(value)
    .trim()
    .replace(/&amp;/g, "&")
    .replace(/^["'`]+/g, "")
    .replace(/["'`]+$/g, "")
    .replace(/[)\],.;]+$/g, "");

  // Sometimes the URL is inside a larger text string
  const match = url.match(/(?:https?:)?\/\/[^\s"'<>\\)\]]+/i);
  if (match) {
    url = match[0];
  }

  // This is the important fix for your error
  if (url.startsWith("//")) {
    url = "https:" + url;
  }

  return url;
}

/**
 * Extract URLs from any nested object/string.
 */
function collectImageUrls(value, urls = new Set(), seen = new Set()) {
  const parsed = parseMaybeJson(value);

  if (typeof parsed === "string") {
    const matches = parsed.match(/(?:https?:)?\/\/[^\s"'<>\\)\]]+/gi) || [];

    for (const raw of matches) {
      const normalized = normalizeImageUrl(raw);

      if (/^https?:\/\//i.test(normalized)) {
        urls.add(normalized);
      }
    }

    return urls;
  }

  if (!parsed || typeof parsed !== "object" || seen.has(parsed)) {
    return urls;
  }

  seen.add(parsed);

  if (Array.isArray(parsed)) {
    for (const item of parsed) {
      collectImageUrls(item, urls, seen);
    }

    return urls;
  }

  for (const raw of Object.values(parsed)) {
    collectImageUrls(raw, urls, seen);
  }

  return urls;
}

/**
 * Check if downloaded buffer looks like an image.
 */
function looksLikeImageBuffer(buffer) {
  if (!Buffer.isBuffer(buffer) || buffer.length < 12) return false;

  // JPG
  if (buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff) {
    return true;
  }

  // PNG
  if (
    buffer[0] === 0x89 &&
    buffer[1] === 0x50 &&
    buffer[2] === 0x4e &&
    buffer[3] === 0x47
  ) {
    return true;
  }

  // WEBP
  if (
    buffer.toString("ascii", 0, 4) === "RIFF" &&
    buffer.toString("ascii", 8, 12) === "WEBP"
  ) {
    return true;
  }

  return false;
}

/**
 * Download image as buffer.
 */
function parseHttpImageUrl(rawUrl) {
  let fixedUrl = normalizeImageUrl(rawUrl);

  if (!fixedUrl) {
    throw new Error("Background image URL is empty");
  }

  if (fixedUrl.startsWith("//")) {
    fixedUrl = "https:" + fixedUrl;
  }

  if (!/^https?:\/\//i.test(fixedUrl)) {
    throw new Error("Background image URL is invalid after normalization: " + fixedUrl);
  }

  const match = fixedUrl.match(/^(https?):\/\/([^\/?#:]+)(?::([0-9]+))?([^\s]*)$/i);

  if (!match) {
    throw new Error("Could not parse background image URL without URL module: " + fixedUrl);
  }

  const protocol = match[1].toLowerCase() + ":";
  const hostname = match[2];
  const port = match[3] || "";
  let path = match[4] || "/";

  if (!path.startsWith("/")) {
    path = "/" + path;
  }

  return {
    href: fixedUrl,
    protocol,
    hostname,
    port,
    path,
    origin: protocol + "//" + hostname + (port ? ":" + port : "")
  };
}

function resolveRedirectLocation(location, currentParsed) {
  let nextUrl = String(location || "").trim();

  if (!nextUrl) {
    return "";
  }

  if (nextUrl.startsWith("//")) {
    return currentParsed.protocol + nextUrl;
  }

  if (/^https?:\/\//i.test(nextUrl)) {
    return nextUrl;
  }

  if (nextUrl.startsWith("/")) {
    return currentParsed.origin + nextUrl;
  }

  const currentPath = currentParsed.path.split("?")[0];
  const baseDir = currentPath.includes("/")
    ? currentPath.slice(0, currentPath.lastIndexOf("/") + 1)
    : "/";

  return currentParsed.origin + baseDir + nextUrl;
}

function downloadImageBuffer(rawUrl, redirectCount = 0) {
  if (redirectCount > 5) {
    return Promise.reject(new Error("Too many redirects while downloading background image"));
  }

  let parsed;

  try {
    parsed = parseHttpImageUrl(rawUrl);
  } catch (error) {
    return Promise.reject(
      new Error(
        "Invalid background image URL before request. " +
        "raw-url=" + String(rawUrl).slice(0, 300) +
        ", error=" + error.message
      )
    );
  }

  const client = parsed.protocol === "https:" ? https : http;

  const requestOptions = {
    protocol: parsed.protocol,
    hostname: parsed.hostname,
    port: parsed.port || undefined,
    path: parsed.path,
    method: "GET",
    headers: {
      "User-Agent": "Mozilla/5.0 (compatible; n8n-sharp-compositor/1.0)",
      "Accept": "image/avif,image/webp,image/apng,image/svg+xml,image/*,*/*;q=0.8",
      "Cache-Control": "no-cache"
    }
  };

  return new Promise((resolve, reject) => {
    const request = client.request(requestOptions, (response) => {
      const status = response.statusCode || 0;
      const location = response.headers.location;
      const contentType = String(response.headers["content-type"] || "");

      if (status >= 300 && status < 400 && location) {
        response.resume();

        const nextUrl = resolveRedirectLocation(location, parsed);

        downloadImageBuffer(nextUrl, redirectCount + 1).then(resolve, reject);
        return;
      }

      const chunks = [];

      response.on("data", (chunk) => {
        chunks.push(Buffer.from(chunk));
      });

      response.on("end", () => {
        const buffer = Buffer.concat(chunks);
        const bodyPreview = buffer.toString("utf8", 0, Math.min(buffer.length, 500));

        if (status < 200 || status >= 300) {
          reject(
            new Error(
              "Could not download background image. " +
              "status=" + status +
              ", content-type=" + contentType +
              ", normalized-url=" + parsed.href +
              ", original-url=" + String(rawUrl).slice(0, 250) +
              ", body-preview=" + bodyPreview
            )
          );
          return;
        }

        if (!contentType.startsWith("image/") && !looksLikeImageBuffer(buffer)) {
          reject(
            new Error(
              "Downloaded background URL is not an image. " +
              "status=" + status +
              ", content-type=" + contentType +
              ", normalized-url=" + parsed.href +
              ", original-url=" + String(rawUrl).slice(0, 250) +
              ", body-preview=" + bodyPreview
            )
          );
          return;
        }

        resolve({
          buffer,
          finalUrl: parsed.href,
          contentType,
          sizeBytes: buffer.length
        });
      });

      response.on("error", (error) => {
        reject(
          new Error(
            "Response error while downloading background image. " +
            "message=" + error.message +
            ", normalized-url=" + parsed.href
          )
        );
      });
    });

    request.setTimeout(60000, () => {
      request.destroy(
        new Error("Timed out downloading background image. normalized-url=" + parsed.href)
      );
    });

    request.on("error", (error) => {
      reject(
        new Error(
          "Network error downloading background image. " +
          "message=" + error.message +
          ", normalized-url=" + parsed.href +
          ", original-url=" + String(rawUrl).slice(0, 250)
        )
      );
    });

    request.end();
  });
}

/**
 * XML escaping for SVG text.
 */
function escapeXml(value) {
  return String(value).replace(/[&<>"']/g, (char) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&apos;"
  })[char]);
}

function safeColor(value, fallback) {
  return /^#[0-9a-f]{6}$/i.test(String(value || "")) ? String(value) : fallback;
}

function clampNumber(value, fallback, min, max) {
  const number = Number(value);

  if (!Number.isFinite(number)) return fallback;

  return Math.min(max, Math.max(min, number));
}

function wrapText(text, maxCharsPerLine = 20, maxLines = 3) {
  const clean = String(text || "").trim().replace(/\s+/g, " ");

  if (!clean) return [];

  const words = clean.split(" ");
  const lines = [];
  let current = "";

  for (const word of words) {
    const next = current ? `${current} ${word}` : word;

    if (next.length <= maxCharsPerLine) {
      current = next;
    } else {
      if (current) {
        lines.push(current);
        current = word;
      } else {
        lines.push(word.slice(0, maxCharsPerLine));
        current = word.slice(maxCharsPerLine);
      }
    }

    if (lines.length >= maxLines) break;
  }

  if (current && lines.length < maxLines) {
    lines.push(current);
  }

  return lines;
}

