function beautifyMarketingText(value) {
  return String(value || "")
    .replace(/\s+/g, " ")
    .replace(/(\d+)\s*(liter|litre|liters|litres)\b/gi, "$1L")
    .replace(/(\d+)\s*l\b/gi, "$1L")
    .replace(/\b1Liter\b/gi, "1L")
    .replace(/\b5Liter\b/gi, "5L")
    .replace(/\b10Liter\b/gi, "10L")
    .trim();
}

function simplifyHeadline(value) {
  const text = beautifyMarketingText(value);
  const lower = text.toLowerCase();

  const sizeMatch = text.match(/(?:^|\D)(1L|2L|5L|10L|12L|13L|18L)(?:\D|$)/i);
  const size = sizeMatch ? sizeMatch[1].toUpperCase() : "";

  if (lower.includes("sunflower") && lower.includes("oil") && size) {
    return `${size} Refined Sunflower Oil`;
  }

  if (text.length > 44) {
    return text.slice(0, 44).trim();
  }

  return text;
}

