    new RegExp("(^|\\D)" + size + "\\s*[- ]?\\s*(l|lt|ltr)(\\D|$)", "i"),
    new RegExp("(^|\\D)" + size + "\\s*لتر(\\D|$)", "i")
  ];

  if (capacityPatterns.some((pattern) => pattern.test(text))) {
    return true;
  }

  const compactPatterns = [
    size + "l",
    size + "lt",
    size + "ltr",
    size + "liter",
    size + "litre",
    size + "liters",
    size + "litres",
    size + "لتر",
    size + "ليتر"
  ];

  if (compactPatterns.some((token) => compact.includes(token))) {
