    stroke="#FFFFFF"
    stroke-opacity="0.55"
  />
</svg>
`);

const composites = [
  {
    input: logoBackSvg,
    left: logoLeft - logoPaddingX,
    top: logoTop - logoPaddingY
  },
  {
    input: logoBuffer,
    left: logoLeft,
    top: logoTop
  }
];

/**
/**
 * Product hero placement.
 * المنتج كبير، في الوسط، ونازل للأسفل حتى لا يبدو معلقًا.
 * صندوق النص سيغطي أسفل المنتج قليلًا، وهذا مقصود.
 */
if (contract.product_path) {
  const productBuffer = await sharp(fs.readFileSync(contract.product_path))
    .resize({
      width: Math.round(width * productWidthRatio),
      height: Math.round(height * productHeightRatio),
      fit: "inside"
    })
    .png()
    .toBuffer();

  const productMeta = await sharp(productBuffer).metadata();

  const productWidth = productMeta.width || 0;
  const productHeight = productMeta.height || 0;

  /**
   * ظل خفيف تحت المنتج حتى لا يبدو معلقًا.
   */
  const shadowSvg = Buffer.from(`
  <svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">
    <defs>
      <filter id="blur" x="-50%" y="-50%" width="200%" height="200%">
        <feGaussianBlur stdDeviation="22"/>
      </filter>
    </defs>
    <ellipse
      cx="${Math.round(width * 0.50)}"
      cy="${Math.round(height * 0.795)}"
      rx="${Math.round(width * 0.25)}"
      ry="${Math.round(height * 0.035)}"
      fill="#000000"
      fill-opacity="0.20"
      filter="url(#blur)"
    />
  </svg>
  `);

  composites.push({
    input: shadowSvg,
    left: 0,
    top: 0
  });

  /**
   * المنتج ينتهي داخل منطقة النص قليلًا.
   * هذا يعطي إحساس أنه واقف على الأرض وليس طائرًا.
   */
  const productCenterX = Math.round(width * 0.50);
  const productBottomY = Math.round(height * 1.00);

  composites.push({
    input: productBuffer,
    left: Math.round(productCenterX - productWidth / 2),
    top: Math.round(productBottomY - productHeight)
  });
}

/**
 * Text.
 * نص ثابت فقط، بدون زر.
 */
function beautifyMarketingText(value) {
  return String(value || "")
    .replace(/\s+/g, " ")
    .replace(/(\d+)\s*(liter|litre|liters|litres)\b/gi, "$1L")
    .replace(/(\d+)\s*l\b/gi, "$1L")
    .replace(/\b1Liter\b/gi, "1L")
    .replace(/\b5Liter\b/gi, "5L")
    .replace(/\b10Liter\b/gi, "10L")
    .trim();
}

function simplifyHeadline(value) {
  const text = beautifyMarketingText(value);
  const lower = text.toLowerCase();

  const sizeMatch = text.match(/(?:^|\D)(1L|2L|5L|10L|12L|13L|18L)(?:\D|$)/i);
  const size = sizeMatch ? sizeMatch[1].toUpperCase() : "";

  if (lower.includes("sunflower") && lower.includes("oil") && size) {
    return `${size} Refined Sunflower Oil`;
  }

  if (text.length > 44) {
    return text.slice(0, 44).trim();
  }

  return text;
}

const headlineRaw = simplifyHeadline(String(payload.headline || "").slice(0, 120));

const textPanelX = Math.round(width * 0.10);
const textPanelY = Math.round(height * 0.835);
const textPanelW = Math.round(width * 0.80);
const textPanelH = Math.round(height * 0.095);

const textCenterX = Math.round(textPanelX + textPanelW / 2);
const textCenterY = Math.round(textPanelY + textPanelH * 0.62);

const headlineLines = wrapText(headlineRaw, 30, 2);
const headlineFontSize = headlineLines.length > 1 ? 36 : 42;

const lineGap = 44;
const firstLineY =
  headlineLines.length > 1
    ? textCenterY - Math.round(lineGap / 2)
    : textCenterY;

const headlineSvg = headlineLines
  .map((line, index) => {
    const y = firstLineY + index * lineGap;

    return `<text x="${textCenterX}" y="${y}" text-anchor="middle" font-family="Arial, sans-serif" font-size="${headlineFontSize}" font-weight="700" fill="${headlineColor}">${escapeXml(line)}</text>`;
  })
  .join("");

const textSvg = Buffer.from(`
<svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">
  <rect
    x="${textPanelX}"
    y="${textPanelY}"
    width="${textPanelW}"
    height="${textPanelH}"
    rx="30"
    fill="${panelColor}"
    fill-opacity="0.90"
    stroke="#FFFFFF"
    stroke-opacity="0.45"
  />
  ${headlineSvg}
</svg>
`);

composites.push({
  input: textSvg,
  left: 0,
  top: 0
});

/**
 * Compose final image.
 * Use JPEG instead of PNG because callback JSON has a body-size limit.
 */
let outputWidth = width;
let outputHeight = height;

async function renderJpeg(targetWidth, targetHeight, quality) {
  return sharp(backgroundBuffer)
    .resize(targetWidth, targetHeight, {
      fit: "cover",
      position: "center"
    })
    .composite(composites)
    .flatten({
      background: "#ffffff"
    })
    .jpeg({
      quality,
      mozjpeg: true
    })
    .toBuffer();
}

const maxCallbackImageBytes = 650 * 1024;

let finalBuffer = null;
let finalQuality = null;

for (const quality of [78, 74, 70, 66, 62, 58, 54, 50, 46, 42]) {
  const candidate = await renderJpeg(width, height, quality);

  finalBuffer = candidate;
  finalQuality = quality;

  if (candidate.length <= maxCallbackImageBytes) {
    break;
  }
}

/**
 * If 1080x1350 is still too large, reduce dimensions slightly.
 */
if (finalBuffer.length > maxCallbackImageBytes) {
  outputWidth = Math.round(width * 0.85);
  outputHeight = Math.round(height * 0.85);

  for (const quality of [74, 70, 66, 62, 58, 54, 50, 46, 42]) {
    const candidate = await renderJpeg(outputWidth, outputHeight, quality);

    finalBuffer = candidate;
    finalQuality = quality;

    if (candidate.length <= maxCallbackImageBytes) {
      break;
    }
  }
}

return [
  {
    json: {
      cp: resolved.cp,
      asset_contract: contract,
      provider_creation_id: waitInput.creation_id,
      composed_file: {
        name: `creative-${resolved.cp.job_id}.jpg`,
        mime_type: "image/jpeg",
        data_base64: finalBuffer.toString("base64"),
        size_bytes: finalBuffer.length,
        width: outputWidth,
        height: outputHeight,
        quality: finalQuality
      },
      background_url: downloadedBackground.finalUrl,
      background_download: {
        content_type: downloadedBackground.contentType,
        size_bytes: downloadedBackground.sizeBytes
      }
    }
  }
];

const crypto = require("crypto");

function removeUndefined(value) {
  if (Array.isArray(value)) {
    return value.map(removeUndefined);
  }

  if (value && typeof value === "object") {
    const cleaned = {};

    for (const [key, val] of Object.entries(value)) {
      if (val !== undefined) {
        cleaned[key] = removeUndefined(val);
      }
    }

    return cleaned;
  }

  return value;
}

const item = $json;
const secret = $env.PLATFORM_CALLBACK_SECRET;

if (!secret) {
  throw new Error("Missing PLATFORM_CALLBACK_SECRET in n8n environment");
}

if (!item.cp?.callback_url) {
  throw new Error("Missing callback_url from CP payload");
}

if (!item.composed_file?.data_base64) {
  throw new Error("Missing composed image data_base64");
}

const timestamp = new Date().toISOString();

const nonce =
  "n8n_composed_image_" +
  Date.now() +
  "_" +
  Math.random().toString(36).slice(2);

const file = {
  file_id: String(item.provider_creation_id || item.cp.job_id) + "_composed",
  type: "image",
  name: item.composed_file.name,
  mime_type: item.composed_file.mime_type,
  data_base64: item.composed_file.data_base64,
  size_bytes: item.composed_file.size_bytes,
  width: item.composed_file.width,
  height: item.composed_file.height,
  source: "n8n-sharp-compositor"
};

const publicFile = {
  file_id: file.file_id,
  type: file.type,
  name: file.name,
  mime_type: file.mime_type,
  size_bytes: file.size_bytes,
  width: file.width,
  height: file.height,
  source: file.source
};

const publicAssetContract = {
  brand_id: item.asset_contract?.brand_id || null,
  logo_id: item.asset_contract?.logo_id || null,
  product_asset_id: item.asset_contract?.product_asset_id || null,
  ratio: item.asset_contract?.ratio || null,
  profile_version: item.asset_contract?.profile_version || null
};

/**
 * نرجع شكل الـ body قريبًا من النسخة الأصلية.
 * مهم: نترك signature داخل body فارغًا أثناء حساب التوقيع.
 */
const callbackBody = removeUndefined({
  job_id: item.cp.job_id,
  correlation_id: item.cp.correlation_id,
  idempotency_key: item.cp.idempotency_key,
  workflow_type: "creative_image_generation",
  workflow_version: "creative-image-sharp-v1",
  status: "completed",
  current_step: "Branded image composed and ready for review",

  nonce,
  signature_timestamp: timestamp,
  signature: "",

  outputs: {
    provider: "magnific-background-plus-sharp",
    asset_contract: publicAssetContract,
    background_url: item.background_url,
    files: [publicFile]
  },

  files: [file],
  warnings: []
});

const raw = JSON.stringify(callbackBody);

const signature = crypto
  .createHmac("sha256", secret)
  .update(timestamp + "." + nonce + "." + raw)
  .digest("hex");

return [
  {
    json: {
      callback_url: item.cp.callback_url,
      callback_headers: {
        signature,
        timestamp,
        nonce
      },
      callback_body: callbackBody,
      callback_debug: {
        body_size_bytes: Buffer.byteLength(raw, "utf8"),
        file_size_bytes: item.composed_file.size_bytes,
        file_mime_type: item.composed_file.mime_type,
        file_name: item.composed_file.name,
        has_body_nonce: true,
        has_body_signature_timestamp: true,
        has_body_signature_field: true
      }
    }
  }
];
